package com.phoenix.business.repository; import com.phoenix.business.domain.Payment; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import org.springframework.data.domain.*; import java.math.BigDecimal; import java.time.Instant; import java.util.List; public interface PaymentRepository extends JpaRepository<Payment,Long>{Page<Payment> findByPaymentDateBetween(Instant from,Instant to,Pageable p); List<Payment> findTop10ByOrderByPaymentDateDesc(); List<Payment> findByMemberIdOrderByPaymentDateDesc(Long id); @Query("select coalesce(sum(p.amount),0) from Payment p where p.status='PAID' and p.paymentDate between :a and :b") BigDecimal revenue(@Param("a") Instant a,@Param("b") Instant b); long countByPaymentDateBetween(Instant a,Instant b);}
